from dataclasses import dataclass

@dataclass
class Order:
    id: int
    total_cents: int

def list_orders(connection: sqlite3.Connection, account_id: str) -> list[Order]:
    query = "SELECT id, total_cents FROM orders WHERE account_id = ?"
    rows = connection.execute(query, (account_id,)).fetchall()
    return [Order(id=row[0], total_cents=row[1]) for row in rows]
